    "id": "navigation/atlassian-multi-target-skip-links",
    "kind": "pattern",
    "title": "Multi-target skip links (\"Skip to: Top Bar · Sidebar · Main Content\") as the first focusable element of an app shell",
    "pattern": "navigation",
